<?php $raw=file_get_contents("database/seeders/careers_data.json"); $existing=json_decode($raw,true); $tech_raw=file_get_contents("database/seeders/careers_data_tech.json"); $tech=json_decode($tech_raw,true); if($tech){ $all=array_merge($tech,$existing); file_put_contents("database/seeders/careers_data.json",json_encode($all,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT)); echo count($all)." total"; } else echo "tech fail: ".json_last_error_msg();
